    WHEN EXCLUDED."annual_fee_known" THEN EXCLUDED."annual_fee_paise"
    ELSE "instruments"."annual_fee_paise"
  END,
  "annual_fee_known" = "instruments"."annual_fee_known" OR EXCLUDED."annual_fee_known",
